import React, { useRef, useState, useEffect } from "react";
import { Html5Qrcode } from "html5-qrcode";

function QRScanner() {
  const scannerRef = useRef(null);
  const beepRef = useRef(null);

  const [isScanning, setIsScanning] = useState(false);
  const [student, setStudent] = useState(null);

  const [message, setMessage] = useState("");
  const [history, setHistory] = useState([]);
  const [darkMode, setDarkMode] = useState(true);

  // 🔊 Load beep once
  useEffect(() => {
    beepRef.current = new Audio(
      "https://www.soundjay.com/button/sounds/beep-01a.mp3"
    );
  }, []);

  const startScanner = async () => {
    if (!scannerRef.current) {
      scannerRef.current = new Html5Qrcode("reader");
    }

    try {
      await scannerRef.current.start(
        { facingMode: "environment" },
        { fps: 25, qrbox: 250 },
        async (decodedText) => {
          await stopScanner();
          beepRef.current.play();
          handleAttendance(decodedText);
        }
      );

      setIsScanning(true);
      setStudent(null);
      setMessage("");
    } catch (err) {
      console.error("Start Error:", err);
    }
  };

  const stopScanner = async () => {
  try {
    if (scannerRef.current && isScanning) {
      await scannerRef.current.stop();
      await scannerRef.current.clear();
      setIsScanning(false);
    }
  } catch (err) {
    console.warn("Scanner already stopped:", err);
  }
};

  const handleAttendance = async (decodedText) => {
    try {
      const verify = await fetch(
        `http://localhost:5000/verify-user/${decodedText}`
      );
      const verifyData = await verify.json();

      if (!verifyData.success) {
        setStatus("error");
        setMessage("User not found ❌");
        return;
      }

      setStudent(verifyData.user);

      const attendance = await fetch(
        `http://localhost:5000/mark-attendance/${decodedText}`,
        { method: "PUT" }
      );
      const data = await attendance.json();

      const time = new Date().toLocaleTimeString();

      if (data.success) {
        setStatus("success");
        setMessage("Attendance Marked ✅");

        setHistory((prev) => [
          { name: verifyData.user.name, time },
          ...prev,
        ]);
      } else {
        setStatus("warning");
        setMessage("Already Marked ⚠️");
      }
    } catch (err) {
      console.error(err);
      setStatus("error");
      setMessage("Server Error ❌");
    }
  };

  const theme = darkMode
    ? {
        bg: "linear-gradient(135deg,#141e30,#243b55)",
        card: "rgba(255,255,255,0.08)",
        text: "#fff",
      }
    : {
        bg: "#f4f4f4",
        card: "#fff",
        text: "#000",
      };

  return (
    <div style={{ ...styles.page, background: theme.bg, color: theme.text }}>
      
      {/* 🌙 Toggle */}
      <button style={styles.toggle} onClick={() => setDarkMode(!darkMode)}>
        {darkMode ? "🌙 Dark" : "☀ Light"}
      </button>

      <div style={{ ...styles.card, background: theme.card }}>
        <h1>📷 QR Scanner Pro</h1>

        {/* Buttons */}
        {!isScanning ? (
          <button style={styles.startBtn} onClick={startScanner}>
            ▶ Start Scan
          </button>
        ) : (
          <button style={styles.stopBtn} onClick={stopScanner}>
            ⏹ Stop
          </button>
        )}

        {/* Scanner */}
        <div style={styles.scannerBox}>
          <div id="reader" style={{ width: "100%" }}></div>

          {isScanning && <div style={styles.scanLine}></div>}
        </div>

        {/* Result */}
        {student && (
          <div style={styles.result}>
            <h2>{student.name}</h2>
            <p>{student.college_name}</p>
            <h3>{message}</h3>
          </div>
        )}

        {/* History */}
        <div style={styles.history}>
          <h3>Attendance History</h3>
          {history.length === 0 ? (
            <p>No records yet</p>
          ) : (
            history.map((h, i) => (
              <div key={i} style={styles.historyItem}>
                {h.name} - {h.time}
              </div>
            ))
          )}
        </div>
      </div>

      {/* ✅ Animation Fix */}
      <style>
        {`
          @keyframes scan {
            0% { top: 0%; }
            100% { top: 100%; }
          }
        `}
      </style>
    </div>
  );
}

export default QRScanner;

const styles = {
  page: {
    minHeight: "100vh",
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
    fontFamily: "Segoe UI",
  },

  card: {
    padding: "25px",
    borderRadius: "20px",
    width: "400px",
    textAlign: "center",
    backdropFilter: "blur(20px)",
    boxShadow: "0 10px 30px rgba(0,0,0,0.3)",
  },

  startBtn: {
    padding: "10px 20px",
    margin: "10px",
    border: "none",
    borderRadius: "10px",
    background: "#00c6ff",
    color: "#fff",
    cursor: "pointer",
  },

  stopBtn: {
    padding: "10px 20px",
    margin: "10px",
    border: "none",
    borderRadius: "10px",
    background: "#ff4b2b",
    color: "#fff",
    cursor: "pointer",
  },

  scannerBox: {
    position: "relative",
    marginTop: "20px",
    borderRadius: "10px",
    overflow: "hidden",
    border: "2px dashed #aaa",
  },

  scanLine: {
    position: "absolute",
    width: "100%",
    height: "3px",
    background: "red",
    animation: "scan 2s linear infinite",
  },

  result: {
    marginTop: "15px",
  },

  history: {
    marginTop: "20px",
    textAlign: "left",
  },

  historyItem: {
    padding: "5px",
    borderBottom: "1px solid #ccc",
  },

  toggle: {
    position: "absolute",
    top: "20px",
    right: "20px",
    padding: "8px",
    borderRadius: "10px",
    border: "none",
    cursor: "pointer",
  },
};
